-- CP221 / S-09: append-only actual emergency incident and event chain.
CREATE TABLE IF NOT EXISTS public.care_tour_stop_emergencies(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),tour_id uuid NOT NULL REFERENCES public.care_tours(id),stop_id uuid NOT NULL REFERENCES public.care_tour_stops(id) ON DELETE RESTRICT,client_id uuid NOT NULL REFERENCES public.clients(id),
 observed_facts text NOT NULL CHECK(length(btrim(observed_facts))>=10),severity text NOT NULL CHECK(severity IN('urgent','life_threatening')),
 client_request_id uuid NOT NULL,request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),opened_by uuid NOT NULL REFERENCES auth.users(id),opened_by_name text NOT NULL,opened_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,client_request_id)
);
CREATE TABLE IF NOT EXISTS public.care_tour_stop_emergency_events(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),incident_id uuid NOT NULL REFERENCES public.care_tour_stop_emergencies(id) ON DELETE RESTRICT,stop_id uuid NOT NULL REFERENCES public.care_tour_stops(id) ON DELETE RESTRICT,sequence_no integer NOT NULL CHECK(sequence_no>0),
 event_kind text NOT NULL CHECK(event_kind IN('immediate_measure','contact_attempt','contact_result','handover','follow_up','closure')),detail text NOT NULL CHECK(length(btrim(detail))>=5),channel text,target_label text,reference_event_id uuid REFERENCES public.care_tour_stop_emergency_events(id) ON DELETE RESTRICT,outcome text,recipient_name text,recipient_role text,responsibility text,confirmation text,assignee_label text,due_at timestamptz,no_handover_reason text,
 CHECK((event_kind='contact_attempt' AND outcome IS NULL)OR event_kind<>'contact_attempt'),
 client_request_id uuid NOT NULL,request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),recorded_by uuid NOT NULL REFERENCES auth.users(id),recorded_by_name text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(incident_id,sequence_no),UNIQUE(tenant_id,client_request_id)
);
ALTER TABLE public.care_tour_stop_emergencies ENABLE ROW LEVEL SECURITY;ALTER TABLE public.care_tour_stop_emergency_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.care_tour_stop_emergencies,public.care_tour_stop_emergency_events FROM PUBLIC,anon,authenticated;GRANT SELECT ON public.care_tour_stop_emergencies,public.care_tour_stop_emergency_events TO authenticated;
DROP POLICY IF EXISTS care_stop_emergencies_read ON public.care_tour_stop_emergencies;
DROP POLICY IF EXISTS care_stop_emergency_events_read ON public.care_tour_stop_emergency_events;
CREATE POLICY care_stop_emergencies_read ON public.care_tour_stop_emergencies FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('pflege.plans.view'));
CREATE POLICY care_stop_emergency_events_read ON public.care_tour_stop_emergency_events FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('pflege.plans.view'));

CREATE OR REPLACE FUNCTION care_private.stop_emergency_context(p_stop_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t uuid:=public.current_tenant_id();s public.care_tour_stops;tr public.care_tours;i public.care_tour_stop_emergencies;
BEGIN IF t IS NULL OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;SELECT * INTO s FROM public.care_tour_stops WHERE id=p_stop_id AND tenant_id=t;IF NOT FOUND THEN RAISE EXCEPTION 'Einsatz nicht gefunden.' USING ERRCODE='42501';END IF;SELECT * INTO tr FROM public.care_tours WHERE id=s.tour_id AND tenant_id=t;IF NOT FOUND OR NOT care_private.stop_opening_allowed(tr) OR NOT public.has_permission('pflege.plans.manage') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;SELECT * INTO i FROM public.care_tour_stop_emergencies WHERE tenant_id=t AND stop_id=s.id ORDER BY opened_at DESC,id DESC LIMIT 1;
 RETURN jsonb_build_object('stopId',s.id,'stopUpdatedAt',s.updated_at,'incident',CASE WHEN i.id IS NULL THEN NULL ELSE jsonb_build_object('id',i.id,'severity',i.severity,'observedFacts',i.observed_facts,'openedAt',i.opened_at,'openedByName',i.opened_by_name,'closed',EXISTS(SELECT 1 FROM public.care_tour_stop_emergency_events e WHERE e.incident_id=i.id AND e.event_kind='closure'),'events',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',e.id,'sequence',e.sequence_no,'kind',e.event_kind,'detail',e.detail,'channel',e.channel,'targetLabel',e.target_label,'referenceEventId',e.reference_event_id,'outcome',e.outcome,'recipientName',e.recipient_name,'recipientRole',e.recipient_role,'responsibility',e.responsibility,'confirmation',e.confirmation,'assigneeLabel',e.assignee_label,'dueAt',e.due_at,'recordedByName',e.recorded_by_name,'recordedAt',e.recorded_at)ORDER BY e.sequence_no)FROM public.care_tour_stop_emergency_events e WHERE e.incident_id=i.id),'[]'::jsonb))END);
END $$;

CREATE OR REPLACE FUNCTION care_private.open_stop_emergency(p_stop_id uuid,p_expected_stop_updated_at timestamptz,p_observed_facts text,p_severity text,p_immediate_measure text,p_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t uuid:=public.current_tenant_id();s public.care_tour_stops;tr public.care_tours;i public.care_tour_stop_emergencies;fp text;actor_name text;actual_time timestamptz;incident_id uuid;
BEGIN IF t IS NULL OR auth.uid() IS NULL OR p_request_id IS NULL OR p_expected_stop_updated_at IS NULL OR length(btrim(COALESCE(p_observed_facts,'')))<10 OR p_severity NOT IN('urgent','life_threatening') OR length(btrim(COALESCE(p_immediate_measure,'')))<5 THEN RAISE EXCEPTION 'Ereignis, Dringlichkeit und tatsächlich veranlasste Sofortmaßnahme vollständig dokumentieren.' USING ERRCODE='23514';END IF;fp:=md5(jsonb_build_object('stopId',p_stop_id,'expected',p_expected_stop_updated_at,'facts',btrim(p_observed_facts),'severity',p_severity,'measure',btrim(p_immediate_measure))::text);PERFORM pg_advisory_xact_lock(hashtext(t::text),hashtext(p_request_id::text));SELECT * INTO i FROM public.care_tour_stop_emergencies WHERE tenant_id=t AND client_request_id=p_request_id;IF FOUND THEN IF i.opened_by IS DISTINCT FROM auth.uid() OR i.request_fingerprint IS DISTINCT FROM fp THEN RAISE EXCEPTION 'Diese Notfallanfrage wurde bereits anders verwendet.' USING ERRCODE='40001';END IF;RETURN jsonb_build_object('incidentId',i.id,'duplicate',true);END IF;
 SELECT * INTO s FROM public.care_tour_stops WHERE id=p_stop_id AND tenant_id=t FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Einsatz nicht gefunden.' USING ERRCODE='42501';END IF;SELECT * INTO tr FROM public.care_tours WHERE id=s.tour_id AND tenant_id=t FOR UPDATE;IF NOT FOUND OR NOT care_private.stop_opening_allowed(tr) OR NOT public.has_permission('pflege.plans.manage') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;IF tr.status<>'in_progress' OR s.status<>'in_progress' OR s.updated_at IS DISTINCT FROM p_expected_stop_updated_at THEN RAISE EXCEPTION 'Einsatz wurde geändert oder ist nicht in tatsächlicher Durchführung.' USING ERRCODE='40001';END IF;IF EXISTS(SELECT 1 FROM public.care_tour_stop_emergencies x WHERE x.tenant_id=t AND x.stop_id=s.id AND NOT EXISTS(SELECT 1 FROM public.care_tour_stop_emergency_events e WHERE e.incident_id=x.id AND e.event_kind='closure'))THEN RAISE EXCEPTION 'Für diesen Einsatz ist bereits ein offener Notfallvorgang vorhanden.' USING ERRCODE='40001';END IF;actual_time:=clock_timestamp();actor_name:=COALESCE(NULLIF(public.clinical_actor_name(),''),NULLIF(tr.employee_name_snapshot,''),'Unbekannt');INSERT INTO public.care_tour_stop_emergencies(tenant_id,tour_id,stop_id,client_id,observed_facts,severity,client_request_id,request_fingerprint,opened_by,opened_by_name,opened_at)VALUES(t,tr.id,s.id,s.client_id,btrim(p_observed_facts),p_severity,p_request_id,fp,auth.uid(),actor_name,actual_time)RETURNING id INTO incident_id;INSERT INTO public.care_tour_stop_emergency_events(tenant_id,incident_id,stop_id,sequence_no,event_kind,detail,client_request_id,request_fingerprint,recorded_by,recorded_by_name,recorded_at)VALUES(t,incident_id,s.id,1,'immediate_measure',btrim(p_immediate_measure),gen_random_uuid(),md5(jsonb_build_object('measure',btrim(p_immediate_measure))::text),auth.uid(),actor_name,actual_time);RETURN jsonb_build_object('incidentId',incident_id,'duplicate',false);
END $$;

CREATE OR REPLACE FUNCTION care_private.record_stop_emergency_event(p_incident_id uuid,p_kind text,p_detail text,p_channel text,p_target_label text,p_reference_event_id uuid,p_outcome text,p_recipient_name text,p_recipient_role text,p_responsibility text,p_confirmation text,p_assignee_label text,p_due_at timestamptz,p_no_handover_reason text,p_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t uuid:=public.current_tenant_id();i public.care_tour_stop_emergencies;s public.care_tour_stops;tr public.care_tours;e public.care_tour_stop_emergency_events;ref public.care_tour_stop_emergency_events;fp text;seq integer;actor_name text;actual_time timestamptz;event_id uuid;
BEGIN IF t IS NULL OR auth.uid() IS NULL OR p_request_id IS NULL OR p_kind NOT IN('immediate_measure','contact_attempt','contact_result','handover','follow_up','closure') OR length(btrim(COALESCE(p_detail,'')))<5 THEN RAISE EXCEPTION 'Notfallereignis und tatsächliches Detail sind erforderlich.' USING ERRCODE='23514';END IF;fp:=md5(jsonb_build_object('incidentId',p_incident_id,'kind',p_kind,'detail',btrim(p_detail),'channel',p_channel,'target',p_target_label,'reference',p_reference_event_id,'outcome',p_outcome,'recipient',p_recipient_name,'role',p_recipient_role,'responsibility',p_responsibility,'confirmation',p_confirmation,'assignee',p_assignee_label,'dueAt',p_due_at,'noHandoverReason',p_no_handover_reason)::text);PERFORM pg_advisory_xact_lock(hashtext(t::text),hashtext(p_request_id::text));SELECT * INTO e FROM public.care_tour_stop_emergency_events WHERE tenant_id=t AND client_request_id=p_request_id;IF FOUND THEN IF e.recorded_by IS DISTINCT FROM auth.uid() OR e.request_fingerprint IS DISTINCT FROM fp THEN RAISE EXCEPTION 'Diese Notfallereignisanfrage wurde bereits anders verwendet.' USING ERRCODE='40001';END IF;RETURN jsonb_build_object('eventId',e.id,'duplicate',true);END IF;SELECT * INTO i FROM public.care_tour_stop_emergencies WHERE id=p_incident_id AND tenant_id=t FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Notfallvorgang nicht gefunden.' USING ERRCODE='42501';END IF;SELECT * INTO s FROM public.care_tour_stops WHERE id=i.stop_id AND tenant_id=t FOR UPDATE;SELECT * INTO tr FROM public.care_tours WHERE id=i.tour_id AND tenant_id=t FOR UPDATE;IF NOT FOUND OR NOT care_private.stop_opening_allowed(tr) OR NOT public.has_permission('pflege.plans.manage') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;IF EXISTS(SELECT 1 FROM public.care_tour_stop_emergency_events x WHERE x.incident_id=i.id AND x.event_kind='closure')THEN RAISE EXCEPTION 'Abgeschlossener Notfallverlauf ist unveränderlich.' USING ERRCODE='40001';END IF;
 IF p_kind='contact_attempt' AND (p_outcome IS NOT NULL OR p_channel NOT IN('phone','in_person','emergency_service','office','contact_person','other') OR length(btrim(COALESCE(p_target_label,'')))<2)THEN RAISE EXCEPTION 'Kontaktversuch darf kein Kontaktergebnis vorwegnehmen; Kontaktweg und tatsächlich adressiertes Ziel angeben.' USING ERRCODE='23514';END IF;IF p_kind IN('contact_result','handover')THEN SELECT * INTO ref FROM public.care_tour_stop_emergency_events WHERE id=p_reference_event_id AND incident_id=i.id AND tenant_id=t;IF NOT FOUND OR(p_kind='contact_result'AND ref.event_kind<>'contact_attempt')OR(p_kind='handover'AND(ref.event_kind<>'contact_result'OR ref.outcome<>'reached'))THEN RAISE EXCEPTION 'Tatsächlicher Kontaktbezug fehlt oder passt nicht.' USING ERRCODE='23514';END IF;END IF;IF p_kind='contact_result'AND(p_outcome NOT IN('reached','no_answer','failed')OR(p_outcome='reached'AND length(btrim(p_detail))<5))THEN RAISE EXCEPTION 'Tatsächliches Kontaktergebnis vollständig dokumentieren.' USING ERRCODE='23514';END IF;IF p_kind='handover'AND(length(btrim(COALESCE(p_recipient_name,'')))<2 OR length(btrim(COALESCE(p_recipient_role,'')))<2 OR length(btrim(COALESCE(p_responsibility,'')))<5 OR length(btrim(COALESCE(p_confirmation,'')))<5)THEN RAISE EXCEPTION 'Bestätigte Übergabe und übernommene Zuständigkeit vollständig dokumentieren.' USING ERRCODE='23514';END IF;IF p_kind='follow_up'AND(length(btrim(COALESCE(p_assignee_label,'')))<2 OR p_due_at IS NULL OR p_due_at<=clock_timestamp())THEN RAISE EXCEPTION 'Folgeauftrag benötigt Zuständigkeit und zukünftige Frist.' USING ERRCODE='23514';END IF;IF p_kind='closure'THEN IF p_outcome NOT IN('transferred','stabilized','other')THEN RAISE EXCEPTION 'Tatsächlichen Abschlussausgang angeben.' USING ERRCODE='23514';END IF;IF NOT EXISTS(SELECT 1 FROM public.care_tour_stop_emergency_events x WHERE x.incident_id=i.id AND x.event_kind='handover')AND length(btrim(COALESCE(p_no_handover_reason,'')))<5 THEN RAISE EXCEPTION 'Abschluss benötigt eine bestätigte Übergabe oder konkreten Grund ohne Übergabe.' USING ERRCODE='23514';END IF;IF NOT EXISTS(SELECT 1 FROM public.care_tour_stop_emergency_events x WHERE x.incident_id=i.id AND x.event_kind='follow_up')THEN RAISE EXCEPTION 'Verbindlicher Folgeauftrag fehlt.' USING ERRCODE='23514';END IF;END IF;
 SELECT COALESCE(max(sequence_no),0)+1 INTO seq FROM public.care_tour_stop_emergency_events WHERE incident_id=i.id;actual_time:=clock_timestamp();actor_name:=COALESCE(NULLIF(public.clinical_actor_name(),''),NULLIF(tr.employee_name_snapshot,''),'Unbekannt');INSERT INTO public.care_tour_stop_emergency_events(tenant_id,incident_id,stop_id,sequence_no,event_kind,detail,channel,target_label,reference_event_id,outcome,recipient_name,recipient_role,responsibility,confirmation,assignee_label,due_at,no_handover_reason,client_request_id,request_fingerprint,recorded_by,recorded_by_name,recorded_at)VALUES(t,i.id,i.stop_id,seq,p_kind,btrim(p_detail),NULLIF(p_channel,''),NULLIF(btrim(COALESCE(p_target_label,'')),''),p_reference_event_id,NULLIF(p_outcome,''),NULLIF(btrim(COALESCE(p_recipient_name,'')),''),NULLIF(btrim(COALESCE(p_recipient_role,'')),''),NULLIF(btrim(COALESCE(p_responsibility,'')),''),NULLIF(btrim(COALESCE(p_confirmation,'')),''),NULLIF(btrim(COALESCE(p_assignee_label,'')),''),p_due_at,NULLIF(btrim(COALESCE(p_no_handover_reason,'')),''),p_request_id,fp,auth.uid(),actor_name,actual_time)RETURNING id INTO event_id;RETURN jsonb_build_object('eventId',event_id,'duplicate',false);
END $$;
CREATE OR REPLACE FUNCTION public.get_ambulatory_care_stop_emergency_context(p_stop_id uuid)RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$SELECT care_private.stop_emergency_context(p_stop_id)$$;
CREATE OR REPLACE FUNCTION public.open_ambulatory_care_stop_emergency(p_stop_id uuid,p_expected_stop_updated_at timestamptz,p_observed_facts text,p_severity text,p_immediate_measure text,p_request_id uuid)RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$SELECT care_private.open_stop_emergency(p_stop_id,p_expected_stop_updated_at,p_observed_facts,p_severity,p_immediate_measure,p_request_id)$$;
CREATE OR REPLACE FUNCTION public.record_ambulatory_care_stop_emergency_event(p_incident_id uuid,p_kind text,p_detail text,p_channel text,p_target_label text,p_reference_event_id uuid,p_outcome text,p_recipient_name text,p_recipient_role text,p_responsibility text,p_confirmation text,p_assignee_label text,p_due_at timestamptz,p_no_handover_reason text,p_request_id uuid)RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$SELECT care_private.record_stop_emergency_event(p_incident_id,p_kind,p_detail,p_channel,p_target_label,p_reference_event_id,p_outcome,p_recipient_name,p_recipient_role,p_responsibility,p_confirmation,p_assignee_label,p_due_at,p_no_handover_reason,p_request_id)$$;
REVOKE ALL ON FUNCTION care_private.stop_emergency_context(uuid),care_private.open_stop_emergency(uuid,timestamptz,text,text,text,uuid),care_private.record_stop_emergency_event(uuid,text,text,text,text,uuid,text,text,text,text,text,text,timestamptz,text,uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.get_ambulatory_care_stop_emergency_context(uuid),public.open_ambulatory_care_stop_emergency(uuid,timestamptz,text,text,text,uuid),public.record_ambulatory_care_stop_emergency_event(uuid,text,text,text,text,uuid,text,text,text,text,text,text,timestamptz,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION care_private.stop_emergency_context(uuid),care_private.open_stop_emergency(uuid,timestamptz,text,text,text,uuid),care_private.record_stop_emergency_event(uuid,text,text,text,text,uuid,text,text,text,text,text,text,timestamptz,text,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_ambulatory_care_stop_emergency_context(uuid),public.open_ambulatory_care_stop_emergency(uuid,timestamptz,text,text,text,uuid),public.record_ambulatory_care_stop_emergency_event(uuid,text,text,text,text,uuid,text,text,text,text,text,text,timestamptz,text,uuid) TO authenticated;

